module scary_subarrays (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] packed_arr,\n    input wire [3:0] n,\n    output reg [5:0] result,\n    output reg done\n);\n\n    // Unpack 8x8-bit array\n    wire [7:0] arr [0:7];\n    assign arr[0] = packed_arr[7:0];\n    assign arr[1] = packed_arr[15:8];\n    assign arr[2] = packed_arr[23:16];\n    assign arr[3] = packed_arr[31:24];\n    assign arr[4] = packed_arr[39:32];\n    assign arr[5] = packed_arr[47:40];\n    assign arr[6] = packed_arr[55:48];\n    assign arr[7] = packed_arr[63:56];\n\n    // State definitions\n    localparam [2:0] IDLE = 3'b000;\n    localparam [2:0] INIT_L = 3'b001;\n    localparam [2:0] CHECK_R = 3'b010;\n    localparam [2:0] COMPARE = 3'b011;\n    localparam [2:0] CHECK_ODD = 3'b100;\n    localparam [2:0] INCREMENT_R = 3'b101;\n    localparam [2:0] INCREMENT_L = 3'b110;\n    localparam [2:0] DONE_ST = 3'b111;\n\n    // State registers\n    reg [2:0] state;\n    reg [2:0] l;\n    reg [2:0] r;\n    reg [2:0] count_less;\n    reg [5:0] result_reg;\n    reg [7:0] temp_arr_l;\n\n    // Combinational signals\n    wire [2:0] diff = r - l;\n    wire diff_even = ~diff[0];\n    wire [2:0] target_count = diff >> 1;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            l <= 3'd0;\n            r <= 3'd0;\n            count_less <= 3'd0;\n            result_reg <= 6'd0;\n            temp_arr_l <= 8'd0;\n            done <= 1'b0;\n        end else begin\n            done <= 1'b0;\n\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= INIT_L;\n                        result_reg <= 6'd0;\n                    end\n                end\n\n                INIT_L: begin\n                    l <= 3'd0;\n                    temp_arr_l <= arr[0];\n                    count_less <= 3'd0;\n                    r <= 3'd0;\n                    state <= CHECK_R;\n                end\n\n                CHECK_R: begin\n                    if (r < n) begin\n                        state <= COMPARE;\n                    end else begin\n                        state <= INCREMENT_L;\n                    end\n                end\n\n                COMPARE: begin\n                    if (arr[r] < temp_arr_l) begin\n                        count_less <= count_less + 3'd1;\n                    end\n                    state <= CHECK_ODD;\n                end\n\n                CHECK_ODD: begin\n                    if (diff_even && (count_less == target_count)) begin\n                        result_reg <= result_reg + 6'd1;\n                    end\n                    state <= INCREMENT_R;\n                end\n\n                INCREMENT_R: begin\n                    r <= r + 3'd1;\n                    state <= CHECK_R;\n                end\n\n                INCREMENT_L: begin\n                    l <= l + 3'd1;\n                    if (l + 3'd1 < n) begin\n                        temp_arr_l <= arr[l + 3'd1];\n                        count_less <= 3'd0;\n                        r <= l + 3'd1;\n                        state <= CHECK_R;\n                    end else begin\n                        state <= DONE_ST;\n                    end\n                end\n\n                DONE_ST: begin\n                    result <= result_reg;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\n\nendmodule